{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C02"],
      "claim": "Phytoene, a long-chain polyisoprenoid carotenoid, showed absolute oral bioavailability of 58.5 ± 18.9% in humans, indicating that highly lipophilic isoprenoid chains can be well absorbed.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C14"],
      "claim": "A compartmental model in humans estimated phytoene bioavailability at 58%, higher than lycopene, supporting the absorbability of long isoprenoid lipids.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C10"],
      "claim": "Hyperforin, a prenylated polyphenol with multiple isoprenoid units, demonstrated high oral bioavailability in volunteers, supporting that prenylated/polyprenylated structures can be orally absorbed.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "Mycophenolate mofetil, a lipophilic isoprenoid-containing prodrug, showed 94.1% oral bioavailability in healthy volunteers, though its ester prodrug design limits direct analogy.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C13"],
      "claim": "All-trans lycopene reached 23.2% bioavailability in healthy adults when consumed as a 13C-labeled dose, demonstrating that some carotenoid/isoprenoid forms can exceed the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "Lycopene from tomato paste showed only 0.17% systemic availability in humans, indicating that certain highly conjugated carotenoids can be very poorly absorbed.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C12"],
      "claim": "Tocotrienol-rich palm oil fraction was reported to have poor oral bioavailability, suggesting that some chromanol/polyprenyl lipids are poorly absorbed.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is a highly lipophilic polyprenyl quinone. The most structurally similar evidence, phytoene, shows high bioavailability (~58%), and other prenylated/isoprenoid molecules (hyperforin, MMF) also support high absorption. Lycopene and tocotrienol records are less transferable due to rigid conjugation or different headgroup chemistry. Overall, the balance favors F ≥ 20%.",
  "evidence_gaps": [
    "No direct experimental bioavailability data for the exact query molecule or a close quinone-polyprenyl analog.",
    "The effect of the methoxy-substituted quinone headgroup on absorption, efflux, and first-pass metabolism is not directly evidenced.",
    "Most lycopene low-bioavailability data are confounded by food matrix effects and may not reflect the isolated molecule's intrinsic absorbability."
  ],
  "new_evidence_assessment": [
    {
      "applicability": "moderate",
      "card_ids": ["C02"],
      "decision_effect": "strengthened",
      "direction": "supportive",
      "family": "phytoene"
    },
    {
