      "card_ids": ["C10"],
      "decision_effect": "strengthened",
      "direction": "supportive",
      "family": "hyperforin"
    },
    {
      "applicability": "low",
      "card_ids": ["C01"],
      "decision_effect": "strengthened",
      "direction": "supportive",
      "family": "mycophenolate mofetil"
    },
    {
      "applicability": "moderate",
      "card_ids": ["C13"],
      "decision_effect": "strengthened",
      "direction": "supportive",
      "family": "lycopene"
    },
    {
      "applicability": "low",
      "card_ids": ["C07"],
      "decision_effect": "weakened",
      "direction": "contradictory",
      "family": "lycopene"
    },
    {
